def apply(inputs, premises):
    personal_used = False
    carry_on_used = False
    checked_indices = []
    n = len(inputs["item_dimension_sums"])
    for i in range(n):
        if inputs["item_personal_size_eligible"][i] and not personal_used:
            personal_used = True
        elif inputs["item_carry_on_size_eligible"][i] and not carry_on_used:
            carry_on_used = True
        else:
            checked_indices = checked_indices + [i]
    total = int(inputs["ticket_price"])
    for j in range(len(checked_indices)):
        i = checked_indices[j]
        weight = float(inputs["item_weights"][i])
        size = float(inputs["item_dimension_sums"][i])
        overweight = 0
        if weight > 70:
            overweight = int(inputs["overweight_fee_over_70_to_100"])
        elif weight > 53:
            overweight = int(inputs["overweight_fee_over_53_to_70"])
        elif weight > 50:
            overweight = int(inputs["overweight_fee_over_50_to_53"])
        oversize = 0
        if size > 65:
            oversize = int(inputs["oversize_fee_over_65_to_115"])
        elif size > 62:
            oversize = int(inputs["oversize_fee_over_62_to_65"])
        if premises["combine_excess_fees_by_higher_fee"]:
            excess = max(overweight, oversize)
        else:
            excess = overweight + oversize
        base_fee = int(inputs["checked_base_fee_schedule"][j])
        if premises["excess_fee_is_added_to_checked_fee"]:
            total = total + base_fee + excess
        else:
            total = total + max(base_fee, excess)
    return {"answer": total}
